solution.solution.js:
function delay(ms, value) {
  return new Promise(resolve => setTimeout(() => resolve(value), ms));
}

function promisify(fn) {
  return (...args) => new Promise((resolve, reject) => {
    fn(...args, (err, value) => (err ? reject(err) : resolve(value)));
  });
}

function settle(promises) {
  return Promise.all(promises.map(p =>
    Promise.resolve(p).then(
      value => ({ status: "fulfilled", value }),
      reason => ({ status: "rejected", reason }),
    )));
}

unitTests:
test("delay waits", async () => {
  const t = Date.now();
  checkEq(await delay(30, "x"), "x");
  check(Date.now() - t >= 25, "should wait about 30 ms");
});

test("promisify", async () => {
  const divide = (a, b, cb) => setTimeout(() => (b === 0 ? cb(new RangeError("divide by zero")) : cb(null, a / b)), 5);
  const divideAsync = promisify(divide);
  check(divideAsync(1, 2) instanceof Promise, "should return a promise");
  checkEq(await divideAsync(10, 4), 2.5);
  try {
    await divideAsync(1, 0);
    check(false, "should reject");
  } catch (e) {
    check(e instanceof RangeError, "should reject with the callback's error");
  }
});

test("settle reports every outcome in order", async () => {
  const fail = (ms, msg) => new Promise((_, reject) => setTimeout(() => reject(new Error(msg)), ms));
  const results = await settle([delay(20, "a"), fail(5, "bad"), 7]);
  checkEq(results.length, 3);
  checkEq(results[0], { status: "fulfilled", value: "a" });
  checkEq(results[1].status, "rejected");
  checkEq(results[1].reason.message, "bad");
  checkEq(results[2], { status: "fulfilled", value: 7 });
  checkEq(await settle([]), []);
});

